package com.byawasaya.platform.plans;
import java.math.BigDecimal; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import com.fasterxml.jackson.databind.ObjectMapper; import com.byawasaya.platform.audit.AuditService; import jakarta.validation.Valid; import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api/platform/promotions")
public class PromotionController {
 private final JdbcTemplate jdbc; private final ObjectMapper mapper; private final AuditService audit;
 public PromotionController(JdbcTemplate jdbc,ObjectMapper mapper,AuditService audit){this.jdbc=jdbc;this.mapper=mapper;this.audit=audit;}
 public record PromoRequest(@NotBlank @Pattern(regexp="[A-Za-z0-9_-]{3,60}")String code,@Size(max=500)String description,@NotBlank @Pattern(regexp="PERCENT|FIXED")String discountType,@NotNull @DecimalMin("0.01")BigDecimal discountValue,@NotNull Instant startsAt,Instant endsAt,@Min(1)Integer maxRedemptions,@Min(1)@Max(1000)int maxPerTenant,@NotNull List<@Pattern(regexp="[A-Z][A-Z0-9_]{2,39}")String> eligiblePlanCodes,boolean active){}
 @GetMapping public List<Map<String,Object>> list(){return jdbc.queryForList("SELECT id,code,description,discount_type AS \"discountType\",discount_value AS \"discountValue\",starts_at AS \"startsAt\",ends_at AS \"endsAt\",max_redemptions AS \"maxRedemptions\",max_per_tenant AS \"maxPerTenant\",redeemed_count AS \"redeemedCount\",eligible_plan_codes AS \"eligiblePlanCodes\",active,created_at AS \"createdAt\" FROM promo_codes ORDER BY created_at DESC");}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> create(@Valid @RequestBody PromoRequest r,org.springframework.security.core.Authentication auth){String code=r.code().trim().toUpperCase(Locale.ROOT);if(jdbc.queryForObject("SELECT COUNT(*) FROM promo_codes WHERE code=?",Long.class,code)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Promo code already exists.");if(r.endsAt()!=null&&!r.endsAt().isAfter(r.startsAt()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End time must be after start time.");if("PERCENT".equals(r.discountType())&&r.discountValue().compareTo(new BigDecimal("100"))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Percentage discounts cannot exceed 100%.");try{String json=mapper.writeValueAsString(r.eligiblePlanCodes());Map<String,Object> result=jdbc.queryForMap("INSERT INTO promo_codes(id,code,description,discount_type,discount_value,starts_at,ends_at,max_redemptions,max_per_tenant,eligible_plan_codes,active,created_by) VALUES(gen_random_uuid(),?,?,?,?,?,?,?,?,CAST(? AS jsonb),?,?) RETURNING id,code,description,discount_type AS \"discountType\",discount_value AS \"discountValue\",starts_at AS \"startsAt\",ends_at AS \"endsAt\",max_redemptions AS \"maxRedemptions\",max_per_tenant AS \"maxPerTenant\",redeemed_count AS \"redeemedCount\",eligible_plan_codes AS \"eligiblePlanCodes\",active,created_at AS \"createdAt\"",code,r.description(),r.discountType(),r.discountValue(),r.startsAt(),r.endsAt(),r.maxRedemptions(),r.maxPerTenant(),json,r.active(),auth.getName());audit.record(auth.getName(),"SUPERADMIN",null,"PROMO_CREATED","PROMO",String.valueOf(result.get("id")),"SUCCESS","{}");return result;}catch(Exception e){if(e instanceof ResponseStatusException rse)throw rse;throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Could not create promotion.");}}
 @PatchMapping("/{id}/active") public Map<String,Object> active(@PathVariable UUID id,@RequestBody Map<String,Boolean> body,org.springframework.security.core.Authentication auth){Boolean active=body.get("active");if(active==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"active is required.");int n=jdbc.update("UPDATE promo_codes SET active=? WHERE id=?",active,id);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Promo code not found.");audit.record(auth.getName(),"SUPERADMIN",null,active?"PROMO_ACTIVATED":"PROMO_DEACTIVATED","PROMO",id.toString(),"SUCCESS","{}");return jdbc.queryForMap("SELECT id,code,active FROM promo_codes WHERE id=?",id);}
}
